module App
  class Paginator
    def initialize(items, per_page)
      @items = items
      @per_page = per_page
    end

    def total_pages
      return 1 if @items.empty?
      @items.size / @per_page
    end

    def page(n)
      tp = total_pages
      p = n < 1 ? 1 : (n > tp ? tp : n)
      start = (p - 1) * @per_page
      {
        items: @items.slice(start, @per_page) || [],
        page: p,
        total_pages: tp,
        total: @items.size,
      }
    end
  end
end
